function validate([nums, minK, maxK]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100000) return 'nums needs 2 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each value of nums is an integer from 1 to 10^6.';
  if (!Number.isInteger(minK) || minK < 1 || minK > 1000000) return 'minK is an integer from 1 to 10^6.';
  if (!Number.isInteger(maxK) || maxK < 1 || maxK > 1000000) return 'maxK is an integer from 1 to 10^6.';
  return null;
}

