function countSubarrays(nums, minK, maxK) {
  let count = 0;
  let badIndex = -1;
  let minIndex = -1;
  let maxIndex = -1;

  for (let right = 0; right < nums.length; right++) {
    const value = nums[right];
    if (value < minK || value > maxK) {
      badIndex = right;
    }
    if (value === minK) {
      minIndex = right;
    }
    if (value === maxK) {
      maxIndex = right;
    }
    const validStarts = Math.min(minIndex, maxIndex) - badIndex;
    if (validStarts > 0) {
      count += validStarts;
    }
  }
  return count;
}

