function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(2, 10);
    const nums = Array.from({ length: n }, () => pick(1, 7));
    let minK = pick(1, 7), maxK = pick(1, 7);
    if (rand() < 0.8 && minK > maxK) [minK, maxK] = [maxK, minK];
    return [nums, minK, maxK];
  }
  const n = 2000;
  const minK = pick(1, 900000);
  const maxK = rand() < 0.1 ? minK : minK + pick(1, 99999);
  const outside = [0.001, 0.01, 0.05][pick(0, 2)];
  const edge = [0.01, 0.03, 0.2][pick(0, 2)];
  const nums = Array.from({ length: n }, () => {
    const r = rand();
    if (r < outside) return rand() < 0.5 && minK > 1 ? pick(1, minK - 1) : pick(maxK + 1, 1000000);
    if (r < outside + edge) return rand() < 0.5 ? minK : maxK;
    return pick(minK, maxK);
  });
  return [nums, minK, maxK];
}
